@OnlyIn(Dist.CLIENT)
public class DebugInfoHandler
{
	public static void init()
	{
		// 1.21.9 removed the debug text event: registerDebugEntries adds these lines as a debug screen entry.
	}

	@SubscribeEvent
	public static void registerDebugEntries(net.neoforged.neoforge.client.event.RegisterDebugEntriesEvent event)
	{
