		event.register(id, (displayer, level, clientChunk, serverChunk) -> new DebugInfoHandler().onTextRender(displayer));
		event.includeInProfile(id, net.minecraft.client.gui.components.debug.DebugScreenProfile.DEFAULT, net.minecraft.client.gui.components.debug.DebugScreenEntryStatus.IN_OVERLAY);
	}

	public void onTextRender(net.minecraft.client.gui.components.debug.DebugScreenDisplayer textEvent)
	{
		if (!Minecraft.getInstance().getDebugOverlay().showDebugScreen())
			return;
		textEvent.getLeft().add("hunger: " + food);
	}
}

