/** Written by mmt port: since 1.20.5 a food's saturation() is the saturation it gives (nutrition x modifier x 2), not the modifier it was made from. */
private static float mmt$saturationModifier(FoodComponent food) {
	return food.nutrition() == 0 ? 0.0F : food.saturation() / (food.nutrition() * 2.0F);
}

