/** Written by mmt port: 1.21.2 moved a food's effects to its consumable component. The same list as before: each effect with its chance. */
private static List<Pair<StatusEffectInstance, Float>> mmt$foodEffects(ItemStack stack) {
	List<Pair<StatusEffectInstance, Float>> effects = new ArrayList<>();
	ConsumableComponent consumable = stack.get(DataComponentTypes.CONSUMABLE);
	if (consumable == null) return effects;
	for (ConsumeEffect effect : consumable.onConsumeEffects())
		if (effect instanceof ApplyEffectsConsumeEffect apply)
			for (StatusEffectInstance instance : apply.effects()) effects.add(Pair.of(instance, apply.probability()));
	return effects;
}

