package {package};

import io.netty.buffer.Unpooled;
import java.util.HashMap;
import java.util.Map;
import net.fabricmc.fabric.api.networking.v1.PayloadTypeRegistry;
import net.minecraft.network.PacketByteBuf;
import net.minecraft.network.codec.PacketCodec;
import net.minecraft.network.packet.CustomPayload;
import net.minecraft.util.Identifier;

/**
 * Written by mmt port: 1.20.5 replaced channel-plus-buffer packets with typed payloads. Each old channel becomes a
 * payload carrying the same bytes, so the mod's own writes and reads are unchanged.
 */
public record MmtPacket(CustomPayload.Id<MmtPacket> id, byte[] bytes) implements CustomPayload {
	private static final Map<Identifier, CustomPayload.Id<MmtPacket>> TYPES = new HashMap<>();

	/** The payload type for a channel, registered for both directions the first time the mod names it. */
	public static synchronized CustomPayload.Id<MmtPacket> type(Identifier channel) {
		CustomPayload.Id<MmtPacket> known = TYPES.get(channel);
		if (known != null) return known;
		CustomPayload.Id<MmtPacket> id = new CustomPayload.Id<>(channel);
		PacketCodec<PacketByteBuf, MmtPacket> codec = PacketCodec.of((packet, buf) -> buf.writeBytes(packet.bytes()), buf -> {
			byte[] bytes = new byte[buf.readableBytes()];
			buf.readBytes(bytes);
			return new MmtPacket(id, bytes);
		});
		PayloadTypeRegistry.playS2C().register(id, codec);
		PayloadTypeRegistry.playC2S().register(id, codec);
		TYPES.put(channel, id);
		return id;
	}

	/** A payload holding what the buffer holds now. */
	public static MmtPacket of(Identifier channel, PacketByteBuf buf) {
		byte[] bytes = new byte[buf.readableBytes()];
		buf.getBytes(buf.readerIndex(), bytes);
		return new MmtPacket(type(channel), bytes);
	}

	/** The bytes as a buffer to read, as the old handler received them. */
	public PacketByteBuf buf() {
		return new PacketByteBuf(Unpooled.wrappedBuffer(bytes));
	}

	@Override
	public CustomPayload.Id<MmtPacket> getId() {
		return id;
	}
}

