/** Written by mmt port: NeoForge 1.21.6 dropped GuiGraphics.drawString at float positions, which drew the text and returned where it ended; the game's own drawString returns nothing now. */
private static int mmt$drawString(GuiGraphics graphics, Font font, String text, float x, float y, int color, boolean shadow) {
	if (text == null) return 0;
	graphics.drawString(font, text, (int) x, (int) y, color, shadow);
	return (int) (x + font.width(text)) + (shadow ? 1 : 0);
}

