/** Written by mmt port: 1.21.5 made the saddle an equipment slot and removed equipSaddle(ItemStack, SoundSource); with a sound source it played the saddling sound, which the saddle's own equippable component now names. */
private static void mmt$equipSaddle(net.minecraft.world.entity.Mob mob, net.minecraft.world.item.ItemStack saddle, net.minecraft.sounds.SoundSource source) {
	mob.setItemSlot(net.minecraft.world.entity.EquipmentSlot.SADDLE, saddle);
	net.minecraft.world.item.equipment.Equippable equippable = saddle.get(net.minecraft.core.component.DataComponents.EQUIPPABLE);
	if (source != null && equippable != null) mob.level().playSound(null, mob, equippable.equipSound().value(), source, 0.5F, 1.0F);
}

