/** Written by mmt port: 1.21.6's GuiGraphics.drawString returns nothing; before, it returned the x where the text ended, one more with its shadow. */
private static int mmt$drawStringEnd(GuiGraphics graphics, Font font, String text, int x, int y, int color) {
	return mmt$drawStringEnd(graphics, font, text, x, y, color, true);
}

private static int mmt$drawStringEnd(GuiGraphics graphics, Font font, String text, int x, int y, int color, boolean shadow) {
	if (text == null) return x;
	graphics.drawString(font, text, x, y, color, shadow);
	return x + font.width(text) + (shadow ? 1 : 0);
}

private static int mmt$drawStringEnd(GuiGraphics graphics, Font font, FormattedCharSequence text, int x, int y, int color) {
	return mmt$drawStringEnd(graphics, font, text, x, y, color, true);
}

private static int mmt$drawStringEnd(GuiGraphics graphics, Font font, FormattedCharSequence text, int x, int y, int color, boolean shadow) {
	graphics.drawString(font, text, x, y, color, shadow);
	return x + font.width(text) + (shadow ? 1 : 0);
}

private static int mmt$drawStringEnd(GuiGraphics graphics, Font font, Component text, int x, int y, int color) {
	return mmt$drawStringEnd(graphics, font, text, x, y, color, true);
}

private static int mmt$drawStringEnd(GuiGraphics graphics, Font font, Component text, int x, int y, int color, boolean shadow) {
	graphics.drawString(font, text, x, y, color, shadow);
	return x + font.width(text) + (shadow ? 1 : 0);
}

