import net.minecraft.client.renderer.entity.state.EntityRenderState;

import net.minecraft.client.renderer.entity.EntityRenderer;

public class CorpseRenderer extends EntityRenderer<CorpseEntity, CorpseRenderer.MmtState> {

    public CorpseRenderer(EntityRendererProvider.Context context) {
        super(context);
    }

    public ResourceLocation getTextureLocation(CorpseEntity entity) {
        return TEXTURE;
    }

    @Override
    public void render(MmtState state, PoseStack matrixStack, MultiBufferSource buffer, int packedLightIn) {
        CorpseEntity entity = state.mmtEntity;
        float entityYaw = state.mmtYaw;
        float partialTicks = state.mmtPartialTick;
        super.render(state, matrixStack, buffer, packedLightIn);
        matrixStack.pushPose();
        getRenderer(skeleton).render(getRenderer(skeleton).createRenderState(skeleton, 1F), matrixStack, buffer, packedLightIn);
        matrixStack.popPose();
    }


    @Override
    public MmtState createRenderState() {
        return new MmtState();
    }

    @Override
    public void extractRenderState(CorpseEntity entity, MmtState state, float partialTick) {
        super.extractRenderState(entity, state, partialTick);
        state.mmtEntity = entity;
        state.mmtPartialTick = partialTick;
        state.mmtYaw = net.minecraft.util.Mth.lerp(partialTick, entity.yRotO, entity.getYRot());
    }

    /** What render was given before 1.21.2 split it into extracting and drawing a render state. */
